INSERT OR REPLACE INTO "dbc_spell" ("ID", "NameSubtext_lang", "Description_lang", "AuraDescription_lang") VALUES (28835, '', '', 'Additional damage taken from Mark of Zeliek.');
INSERT OR REPLACE INTO "dbc_spell" ("ID", "NameSubtext_lang", "Description_lang", "AuraDescription_lang") VALUES (412798, '', 'You and your demon pet gain dodge chance equal to $s1% of your spell critical strike chance each time you deal a critical strike to an enemy, and also both regain $412800s2% of maximum mana.', '');
INSERT OR REPLACE INTO "dbc_spell" ("ID", "NameSubtext_lang", "Description_lang", "AuraDescription_lang") VALUES (412800, '', 'Increases Dodge chance by a value equal to $412798s1% of your spell critical chance.', 'Dodge chance increased by $w1%.');
INSERT OR REPLACE INTO "dbc_spell" ("ID", "NameSubtext_lang", "Description_lang", "AuraDescription_lang") VALUES (455864, '', 'Your Faerie Fire (Feral) also increases the chance for all attacks to hit that target by $455868s1% for $455868d.', '');
INSERT OR REPLACE INTO "dbc_spell" ("ID", "NameSubtext_lang", "Description_lang", "AuraDescription_lang") VALUES (456533, '', 'Your Seal of Command, Seal of Righteousness, and Seal of Martyrdom now persist for $s1 seconds after you cast another Seal, or until you cast a third Seal. Your Judgements can now trigger multiple Seals if active.', '');
INSERT OR REPLACE INTO "dbc_spell" ("ID", "NameSubtext_lang", "Description_lang", "AuraDescription_lang") VALUES (457475, '', 'The radius of your totems that affect friendly targets is increased to ${$m1+20} yd.', '');
INSERT OR REPLACE INTO "dbc_spell" ("ID", "NameSubtext_lang", "Description_lang", "AuraDescription_lang") VALUES (457494, '', 'Your Healing Wave will now jump to additional nearby targets. Each jump reduces the effectiveness of the heal by $s2%, and the spell will jump to up to ${$m1-1} additional targets.', '');
INSERT OR REPLACE INTO "dbc_spell" ("ID", "NameSubtext_lang", "Description_lang", "AuraDescription_lang") VALUES (457572, '', 'Each time you take damage, you and your pet gain mana equal to the damage taken, up to a maximum of $s1 mana per event. Can only occur once every few seconds.', '');
INSERT OR REPLACE INTO "dbc_spell" ("ID", "NameSubtext_lang", "Description_lang", "AuraDescription_lang") VALUES (467216, '', 'Swipe(Bear) also causes your Maul to hit $467217s1 additional target for the next $467217d.', '');
INSERT OR REPLACE INTO "dbc_spell" ("ID", "NameSubtext_lang", "Description_lang", "AuraDescription_lang") VALUES (467334, '', 'Your periodic damage has a $h% chance to reset the cooldown on one of your Strike abilities. The Strike with the longest remaining cooldown is always chosen.', '');
INSERT OR REPLACE INTO "dbc_spell" ("ID", "NameSubtext_lang", "Description_lang", "AuraDescription_lang") VALUES (467877, '', 'Your chance to trigger Static Shock is increased by $m1% (${$m1/2}% while dual-wielding).', '');
INSERT OR REPLACE INTO "dbc_spell" ("ID", "NameSubtext_lang", "Description_lang", "AuraDescription_lang") VALUES (468067, '', 'Revenge also grants you Flurry, increasing your attack speed by $12970s1% for the next $12970n swings.', '');
INSERT OR REPLACE INTO "dbc_spell" ("ID", "NameSubtext_lang", "Description_lang", "AuraDescription_lang") VALUES (468417, '', 'Increases the Attack Power your Beast pet gains from your attributes by $s1%.', '');
INSERT OR REPLACE INTO "dbc_spell" ("ID", "NameSubtext_lang", "Description_lang", "AuraDescription_lang") VALUES (470240, '', 'While Frostbrand Weapon is active on your main hand weapon, your Water Shield triggers reduce the cast time of your next Chain Lightning spell within $470272d1 by $470272s1%, and increases its damage by $470272s1%. Stacking up to 5 times.', '');
INSERT OR REPLACE INTO "dbc_spell" ("ID", "NameSubtext_lang", "Description_lang", "AuraDescription_lang") VALUES (1213201, '', 'Your melee attacks have $s1% less chance to be Dodged or Parried.', '');
INSERT OR REPLACE INTO "dbc_spell" ("ID", "NameSubtext_lang", "Description_lang", "AuraDescription_lang") VALUES (1213321, '', 'Your Fireball, Frostfire Bolt, and Balefire Bolt spells gain $s1% increased damage for each of your Fire effects on your target, up to a maximum increased of $s2%.', '');
INSERT OR REPLACE INTO "dbc_spell" ("ID", "NameSubtext_lang", "Description_lang", "AuraDescription_lang") VALUES (1213406, '', 'Your basic attacks increase the damage of your next Exorcism cast within $1217927d by $1217927s1%.  Stacking up to $s1 times.', '');
INSERT OR REPLACE INTO "dbc_spell" ("ID", "NameSubtext_lang", "Description_lang", "AuraDescription_lang") VALUES (1213930, '', 'Damaging a target with Stormstrike, Lava Burst, or Molten Blast also reduces all damage you take by $1213934s1% for $1213934d.', '');
INSERT OR REPLACE INTO "dbc_spell" ("ID", "NameSubtext_lang", "Description_lang", "AuraDescription_lang") VALUES (1213937, '', 'When your Spirit of the Alpha is cast on yourself, it also increases your health by $1213939s1%, your threat generated by $1213939s2%, and all damage you deal by $1213939s3%.', '');
INSERT OR REPLACE INTO "dbc_spell" ("ID", "NameSubtext_lang", "Description_lang", "AuraDescription_lang") VALUES (1214095, '', 'The effects of your Demonic Sacrifice now persist while you have a Demon pet active, as long as you do not resummon the sacrificed pet. You may have only one Demonic Sacrifice effect active at a time.', '');
INSERT OR REPLACE INTO "dbc_spell" ("ID", "NameSubtext_lang", "Description_lang", "AuraDescription_lang") VALUES (1217084, '', 'Increases all damage caused against targets in Silithus, Ahn''Qiraj, Eastern Plaguelands, and Naxxramas by $s1% and increases critical damage caused against targets in these areas by an additional $s2%.', 'Damage against targets in Silithus, Ahn''Qiraj, Eastern Plaguelands, and Naxxramas increased by $s1%.' || char(13) || '' || char(10) || 'Critical damage against targets in these areas is also increased by $s2%.');
INSERT OR REPLACE INTO "dbc_spell" ("ID", "NameSubtext_lang", "Description_lang", "AuraDescription_lang") VALUES (1217694, '', '', '');
INSERT OR REPLACE INTO "dbc_spell" ("ID", "NameSubtext_lang", "Description_lang", "AuraDescription_lang") VALUES (1217724, '', 'The torch burns brightly, scorching it''s wielder. ', 'The torch burns brightly, scorching it''s wielder.');
