INSERT OR REPLACE INTO "dbc_spell" ("ID", "NameSubtext_lang", "Description_lang", "AuraDescription_lang") VALUES (1218038, '', 'Bound in ice until the fetters are destroyed.', 'Bound in ice until the fetters are destroyed.');
