INSERT OR REPLACE INTO "dbc_spell" ("ID", "NameSubtext_lang", "Description_lang", "AuraDescription_lang") VALUES (1218271, '', 'The forces of the Scourge grow stronger.', 'The forces of the Scourge grow stronger. Chance to dodge reduced by ${$s1/$u}% and chance to be hit increased by ${$s2/$u}%.' || char(13) || '' || char(10) || '' || char(13) || '' || char(10) || 'The benefits from your Seal of the Dawn cannot exceed Rank $s3.');
