INSERT OR REPLACE INTO "dbc_spell" ("ID", "NameSubtext_lang", "Description_lang", "AuraDescription_lang") VALUES (1218283, '', 'The Lich King himself has taken notice. No hope remains here.', 'The Lich King himself has taken notice. No hope remains here. Chance to dodge reduced by ${$s1/$u}% and chance to be hit increased by ${$s2/$u}%.' || char(13) || '' || char(10) || '' || char(13) || '' || char(10) || 'The benefits from your Seal of the Dawn cannot exceed Rank ${$s3/$u}.');
INSERT OR REPLACE INTO "dbc_spell" ("ID", "NameSubtext_lang", "Description_lang", "AuraDescription_lang") VALUES (1218485, '', 'Increases all damage caused against targets in Silithus, Ahn''Qiraj, Eastern Plaguelands, and Naxxramas by $s1% and increases critical damage caused against targets in these areas by an additional $s2%.', 'Damage against targets in Silithus, Ahn''Qiraj, Eastern Plaguelands, and Naxxramas increased by $s1%.' || char(13) || '' || char(10) || 'Critical damage against targets in these areas is also increased by $s2%.');
INSERT OR REPLACE INTO "dbc_spell" ("ID", "NameSubtext_lang", "Description_lang", "AuraDescription_lang") VALUES (1219369, '', 'You gain $1219370s1% increased damage done to Undead for $1219370d for each time your Overload triggers from an offensive spell cast, stacking up to $1219370u times.', '');
INSERT OR REPLACE INTO "dbc_spell" ("ID", "NameSubtext_lang", "Description_lang", "AuraDescription_lang") VALUES (1219539, '', 'Unlocks your potential while inside Naxxramas.  Increasing your damage by ${$m1/100}.2% and your health by ${$m2/100}.2% for each Sanctified item equipped.  (Equipping more than $1223336s2 Sanctified items provides no additional benefit)', 'Unlocks your potential while inside Naxxramas.  Increasing your damage by ${$m1/100}.2% and your health by ${$m2/100}.2% for each Sanctified item equipped.');
INSERT OR REPLACE INTO "dbc_spell" ("ID", "NameSubtext_lang", "Description_lang", "AuraDescription_lang") VALUES (1219548, '', 'Unlocks your potential while inside Naxxramas.  Increasing your healing by ${$m1/100}.2% and your health by ${$m2/100}.2% for each Sanctified item equipped.  (Equipping more than $1223336s2 Sanctified items provides no additional benefit)', 'Unlocks your potential while inside Naxxramas.  Increasing your healing by ${$m1/100/$u}.2% and your health by ${$m2/100/$u}.2% for each Sanctified item equipped.');
