INSERT OR REPLACE INTO "dbc_spell" ("ID", "NameSubtext_lang", "Description_lang", "AuraDescription_lang") VALUES (1220514, '', 'Unlocks your potential while inside Naxxramas.  Increasing your threat caused by ${$m1/100}.2%, your damage by ${$m2/100}.2%, and your health by ${$m3/100}.2% for each Sanctified item equipped.  (Equipping more than $1223336s2 Sanctified items provides no additional benefit)', 'Unlocks your potential while inside Naxxramas.  Increasing your threat caused by ${$m1/100/$u}.2%, your damage by ${$m2/100/$u}.2%, and your health by ${$m3/100/$u}.2% for each Sanctified item equipped.');
INSERT OR REPLACE INTO "dbc_spell" ("ID", "NameSubtext_lang", "Description_lang", "AuraDescription_lang") VALUES (1220642, '', 'Increases the amount healed by your Chain Heal, Riptide, and Earth Shield spells by $s1%.', '');
