INSERT OR REPLACE INTO "dbc_spell" ("ID", "NameSubtext_lang", "Description_lang", "AuraDescription_lang") VALUES (1220980, '', 'Equipped with state of the art Creepy Censor Sensors, allowing you to see anything! ' || char(13) || '' || char(10) || '' || char(13) || '' || char(10) || 'Disclaimer: Goggles may not allow you to see much at all.', 'Equipped with state of the art Creepy Censor Sensors, allowing you to see anything! ' || char(13) || '' || char(10) || '' || char(13) || '' || char(10) || 'Disclaimer: Goggles may not allow you to see much at all.');
